def generic_transform(grid):
    H,W=len(grid),len(grid[0]); g=[row[:] for row in grid]
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    def runs(arr):
        rr=[]
        i=0
        while i<len(arr):
            j=i+1
            while j<len(arr) and arr[j]==arr[i]: j+=1
            if arr[i]!=bg: rr.append((arr[i],i,j-1))
            i=j
        return rr
    cand=[]
    # (orientation, color, source edges two run segments)
    for ori in ('h','v'):
        if ori=='h': edges=[grid[0],grid[-1]]
        else: edges=[[grid[r][0] for r in range(H)],[grid[r][-1] for r in range(H)]]
        r0,r1=runs(edges[0]),runs(edges[1])
        for c,a,b in r0:
            if b-a+1<3: continue
            options=[(cc,x,y) for cc,x,y in r1 if cc==c and y-x+1>=3]
            for _,x,y in options:
                if ori=='h': cand.append((ori,c,(0,a,b),(H-1,x,y)))
                else: cand.append((ori,c,(a,b,0),(x,y,W-1)))
    if not cand: return g
    # prefer length pair; generally unique
    ori,bcol,barA,barB=max(cand,key=lambda z:min(z[2][2]-z[2][1]+1,z[3][2]-z[3][1]+1))
    dots=[(r,c) for r in range(H) for c in range(W) if grid[r][c] not in (bg,bcol)]
    if not dots: return g
    if ori=='h':
        # bar tuple is (edge row, lo,hi)
        a=barA[1:]; b=barB[1:]
        scoreA=sum(a[0]<=c<=a[1] for r,c in dots); scoreB=sum(b[0]<=c<=b[1] for r,c in dots)
        source,target=(barA,barB) if scoreA>=scoreB else (barB,barA)
        s_axis,t_axis=source[1],target[1]
        s_edge=source[0]; t_edge=target[0]
        active=set()
        # connector pairs on same row separated by at least 4
        for r1,(r,c1) in enumerate(dots):
            for r2,c2 in dots[r1+1:]:
                if r==r2 and abs(c2-c1)>=4:
                    lo,hi=sorted((c1,c2));
                    for c in range(lo,hi+1):
                        g[r][c]=grid[r][c] if grid[r][c] not in (bg,bcol) else next(iter([grid[r1][c1]]))
                        active.add(c)
                if c1==c2 and abs(r2-r)>=4:
                    lo,hi=sorted((r,r2))
                    for rr in range(lo,hi+1): g[rr][c1]=grid[r][c1]
        for r,c in dots:
            col=grid[r][c]; active.add(c)
            if s_edge==0:
                for rr in range(1,r): g[rr][c]=col
            else:
                for rr in range(r+1,H-1): g[rr][c]=col
            g[r][c]=4
        shift=t_axis[0]-s_axis[0]
        for c in active:
            tc=c+shift
            if 0<=tc<W:
                if t_edge==0:
                    for rr in range(1,H): g[rr][tc]=grid[dots[0][0]][dots[0][1]]
                else:
                    for rr in range(H-1): g[rr][tc]=grid[dots[0][0]][dots[0][1]]
    else:
        # barA tuples (lo,hi,edge col)
        a=barA[:2]; b=barB[:2]
        scoreA=sum(a[0]<=r<=a[1] for r,c in dots); scoreB=sum(b[0]<=r<=b[1] for r,c in dots)
        source,target=(barA,barB) if scoreA>=scoreB else (barB,barA)
        s_axis=source[:2]; t_axis=target[:2]
        s_edge=source[2]; t_edge=target[2]
        active=set()
        for idx,(r,c) in enumerate(dots):
            for rr,cc in dots[idx+1:]:
                if r==rr and abs(c-cc)>=4:
                    lo,hi=sorted((c,cc));
                    for x in range(lo,hi+1): g[r][x]=grid[r][c]; active.add(r)
                if c==cc and abs(r-rr)>=4:
                    lo,hi=sorted((r,rr))
                    for y in range(lo,hi+1): g[y][c]=grid[r][c]; active.add(y)
        for r,c in dots:
            col=grid[r][c]; active.add(r)
            if s_edge==0:
                for cc in range(1,c): g[r][cc]=col
            else:
                for cc in range(c+1,W-1): g[r][cc]=col
            g[r][c]=4
        shift=t_axis[0]-s_axis[0]
        for r in active:
            tr=r+shift
            if 0<=tr<H:
                if t_edge==0:
                    for cc in range(W): g[tr][cc]=grid[dots[0][0]][dots[0][1]]
                else:
                    for cc in range(W-1): g[tr][cc]=grid[dots[0][0]][dots[0][1]]
    return g

